// Generated by Claude Code
package ui;

import grading.progress.GradingStatus;
import grading.progress.ProgressSnapshot;
import grading.session.RunOutcome;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Optional;

/** Formats the end of a grading run for the Activity tab: who was graded and where the reports are. */
final class GradingSummaryText {

    private static final String SUMMARY_REPORT = "summary.pdf";

    private GradingSummaryText() {
    }

    /** What the run did, for the header line; the stat tiles show the counts. */
    static String runEnd(RunOutcome outcome, ProgressSnapshot snapshot) {
        long notGraded = snapshot.students().stream().filter(student -> student.status() == GradingStatus.SKIPPED)
                .count();
        return switch (outcome) {
            case CANCELLED -> "Run cancelled; earlier marks kept";
            case FAILED -> "Grading stopped; see the Activity log";
            case COMPLETED, NONE -> notGraded == 0 ? "Run complete" : "Run complete; " + notGraded + " not graded";
        };
    }

    static String format(ProgressSnapshot snapshot, Optional<Path> reportsFolder) {
        // Each student's marks are in the All students table, so the log says only what the table cannot.
        long graded = snapshot.students().stream().filter(student -> student.status() != GradingStatus.SKIPPED)
                .count();
        StringBuilder text = new StringBuilder("Grading results\n")
                .append("Graded ").append(graded).append(" of ").append(snapshot.students().size())
                .append(" students. Their marks are in the All students tab.\n");
        snapshot.students().stream().filter(student -> student.status() == GradingStatus.SKIPPED)
                .forEach(student -> text.append("Not graded: ").append(student.username())
                        .append(" (confirm identity first)\n"));
        text.append("\nReports\n");
        if (reportsFolder.isEmpty()) {
            text.append("No reports were written for this run.\n");
        } else {
            Path folder = reportsFolder.get().toAbsolutePath();
            text.append("Saved in: ").append(folder).append('\n');
            if (Files.exists(folder.resolve(SUMMARY_REPORT))) {
                text.append("The class summary is ").append(SUMMARY_REPORT).append(" in that folder.\n");
            }
            text.append("Select a student and choose Download PDF report to save their report.\n");
        }
        return text.toString();
    }
}
